DROP TABLE IF EXISTS `avatar_table`;
CREATE TABLE `avatar_table` ( `Prop_Number` bigint(20) NOT NULL default '0', `Prop_Name` varchar(30) NOT NULL default '', `Prop_Description` varchar(255) NOT NULL default '',`Prop_Money` int(11) NOT NULL default '0',  `Prop_Cash` int(11) NOT NULL default '0',  `Prop_Type` varchar(10) NOT NULL default '',  `Prop_Sex` varchar(10) NOT NULL default '',  `Prop_Gift` varchar(10) NOT NULL default '',  `Prop_Delay` int(2) NOT NULL default '0',  `Prop_Attack` int(2) NOT NULL default '0',  `Prop_Life` int(2) NOT NULL default '0',  `Prop_Dig` int(2) NOT NULL default '0',  `Prop_Star` int(2) NOT NULL default '0',  `Prop_Def` int(2) NOT NULL default '0',  `Prop_Shield` int(2) NOT NULL default '0',  `Prop_Skip` int(2) NOT NULL default '0', PRIMARY KEY  (`Prop_Number`) ) ENGINE=MyISAM DEFAULT CHARSET=latin1;
